extern "C" uint32_t omni_host_sdk_v1_module_request_node(uint64_t h,uint32_t i,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);if(!m)return 12;if(i>=m->schema.requestRoots.size())return 2;*out=m->schema.requestRoots[i];return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_module_result_node(uint64_t h,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);if(!m)return 12;*out=m->schema.resultRoot;return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_schema_node_kind(uint64_t h,uint32_t i,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);const auto* n=m?node(*m,i):nullptr;if(!n)return m?2:12;*out=n->tag;return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_schema_node_typeid(uint64_t h,uint32_t i,uint8_t out[32]){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);const auto* n=m?node(*m,i):nullptr;if(!n)return m?2:12;std::memcpy(out,n->typeId.data(),32);return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_schema_node_child_count(uint64_t h,uint32_t i,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);const auto* n=m?node(*m,i):nullptr;if(!n)return m?2:12;*out=static_cast<uint32_t>(n->children.size());return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_schema_node_child(uint64_t h,uint32_t i,uint32_t child,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* m=module(h);const auto* n=m?node(*m,i):nullptr;if(!n)return m?2:12;if(child>=n->children.size()||n->children[child]==UINT32_MAX)return 2;*out=n->children[child];return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_schema_node_label_read(uint64_t h,uint32_t i,uint32_t child,uint8_t* out,uint32_t cap,uint32_t* copied){try{std::lock_guard guard(mutex);auto* m=module(h);const auto* n=m?node(*m,i):nullptr;if(!n)return m?2:12;if(child>=n->labels.size())return 2;const auto& label=n->labels[child];return copy(std::span<const uint8_t>(reinterpret_cast<const uint8_t*>(label.data()),label.size()),out,cap,copied);}catch(...){return error();}}
