extern "C" uint32_t omni_host_sdk_v1_value_destroy(uint64_t h){try{std::lock_guard guard(mutex);const auto it=values.find(h);if(it==values.end())return 12;auto* m=module(it->second->module);if(!m||m->live==0)return 12;m->live--;values.erase(it);return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_kind(uint64_t h,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;*out=node(*m,v->node)->tag;return 0;}catch(...){return error();}}
