extern "C" uint32_t omni_host_sdk_v1_value_scalar_set(uint64_t h,uint64_t bits){try{std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;uint64_t normalized=0;const auto status=scalarBits(node(*m,v->node)->tag,bits,normalized);if(status)return status;v->value.bits=normalized;return 0;}catch(...){return error();}}
