extern "C" uint32_t omni_host_sdk_v1_value_data_set(uint64_t h,const uint8_t* data,uint32_t size){try{if(size&&!data)return 2;std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;const auto tag=node(*m,v->node)->tag;if(tag!=0x0b&&tag!=0x0c)return 2;v->value.text.assign(reinterpret_cast<const char*>(data),size);if(tag==0x0b){if(v->value.text.find('\0')!=std::string::npos)return 2;try{omni::validateUTF8(v->value.text);}catch(...){return 2;}}return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_data_read(uint64_t h,uint8_t* out,uint32_t cap,uint32_t* copied){try{std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;const auto tag=node(*m,v->node)->tag;if(tag!=0x0b&&tag!=0x0c)return 2;return copy(std::span<const uint8_t>(reinterpret_cast<const uint8_t*>(v->value.text.data()),v->value.text.size()),out,cap,copied);}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_discriminant_set(uint64_t h,uint32_t d){try{std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;const auto* n=node(*m,v->node);if(n->tag==0x10){if(d>=n->children.size())return 2;v->value.bits=d;}else if(n->tag==0x11){if(d>1)return 2;v->value.bits=d;}else if(n->tag==0x12){if(d>1)return 2;v->value.bits=d==0?1u:0u;}else return 2;v->value.fields.clear();return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_discriminant_get(uint64_t h,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;const auto tag=node(*m,v->node)->tag;if(tag==0x10||tag==0x11)*out=static_cast<uint32_t>(v->value.bits);else if(tag==0x12)*out=v->value.bits?0u:1u;else return 2;return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_child_count(uint64_t h,uint32_t* out){try{if(!out)return 2;std::lock_guard guard(mutex);auto* v=value(h);if(!v)return 12;auto* m=module(v->module);if(!m)return 12;const auto* n=node(*m,v->node);if(n->tag==0x0e)*out=n->extent;else if(n->tag==0x10)*out=(v->value.bits<n->children.size()&&n->children[v->value.bits]!=UINT32_MAX)?1u:0u;else if(n->tag==0x11)*out=v->value.bits?1u:0u;else if(n->tag==0x12)*out=1;else *out=static_cast<uint32_t>(n->children.size());return 0;}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_value_child_set(uint64_t p,uint32_t index,uint64_t c){try{std::lock_guard guard(mutex);auto* parent=value(p);auto* child=value(c);if(!parent||!child)return 12;if(parent->module!=child->module)return 3;auto* m=module(parent->module);if(!m)return 12;uint32_t expected=0;const auto status=childNode(*m,*parent,index,expected);if(status)return status;if(expected!=child->node)return 3;const auto* n=node(*m,parent->node);if(n->tag==0x0e||n->tag==0x0d||n->tag==0x0f){if(parent->value.fields.size()<=index)parent->value.fields.resize(index+1);parent->value.fields[index]=child->value;}else {parent->value.fields.assign(1,child->value);}return 0;}catch(...){return error();}}
