extern "C" uint32_t omni_host_sdk_v1_request_encode(uint64_t h,const uint64_t* args,uint32_t count,uint8_t* out,uint32_t cap,uint32_t* copied){try{if(!copied||(count&&!args)||(cap&&!out))return 2;std::lock_guard guard(mutex);auto* m=module(h);if(!m)return 12;if(count!=m->request.size())return 2;std::vector<Value> native;native.reserve(count);for(uint32_t i=0;i<count;i++){auto* v=value(args[i]);if(!v)return 12;if(v->module!=h||v->node!=m->schema.requestRoots[i])return 3;native.push_back(v->value);}const auto frame=omni::encodeInvocationFrame(m->program,1,m->schema.signature,m->request,native);return copy(frame,out,cap,copied);}catch(...){return error();}}
extern "C" uint32_t omni_host_sdk_v1_result_decode(uint64_t h,const uint8_t* frame,uint32_t length,uint64_t* out){try{if(!out||(length&&!frame))return 2;std::lock_guard guard(mutex);auto* m=module(h);if(!m)return 12;const std::vector<Type> expected{m->result};const auto decoded=omni::decodeInvocationFrame(m->program,std::span<const uint8_t>(frame,length),2,m->schema.signature,expected);if(decoded.size()!=1)return 10;return createValue(*m,h,m->schema.resultRoot,decoded[0],out);}catch(...){return error();}}
